  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    # Build mutual reachability edges
    edges = []
    for u, v, d in distances:
        if u not in core or v not in core:
            raise ValueError('Missing core distance')
        mr = max(core[u], core[v], d)
        # Canonicalize: store (node1, node2) in sorted order for tie-breaking
        a, b = (u, v) if u < v else (v, u)
        edges.append((mr, a, b))
    # Sort by weight, then by first node, then second node
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    selected = []
    total = 0.0
    for w, a, b in edges:
        if union(a, b):
            selected.append({'source': a, 'target': b, 'weight': w})
            total += w
            if len(selected) == n - 1:
                break
    if len(selected) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'edges': selected, 'total_weight': total}
